  1367  void smtp_server_connection_reset_state(struct smtp_server_connection *conn)
  1368  {
  1369          e_debug(conn->event, "Connection state reset");
  1370
  1371          i_free(conn->state.args);
  1372
  1373          if (conn->state.trans != NULL)
  1374                  smtp_server_transaction_free(&conn->state.trans);
  1375
  1376          /* RFC 3030, Section 2:
  1377             The RSET command, when issued after the first BDAT and before the
  1378             BDAT LAST, clears all segments sent during that transaction and resets
  1379             the session.
  1380           */
  1381          i_stream_destroy(&conn->state.data_input);
  1382          i_stream_destroy(&conn->state.data_chain_input);
  1383          conn->state.data_chain = NULL;
  1384
  1385          /* Reset state */
  1386          i_zero(&conn->state);
  1387          smtp_server_connection_set_state(conn, SMTP_SERVER_STATE_READY, NULL);
  1388  }
